-- ข่าวตัวอย่างรอบที่ 2: อีก 10 เรื่อง (5 หมวด หมวดละ 2 เรื่อง)
-- ภาพปกอยู่ที่ uploads/sample/sample-news-11.jpg ... 20.jpg (อัปโหลดเข้าโฟลเดอร์ uploads/sample บนเซิร์ฟเวอร์)
-- นำเข้าซ้ำได้ (ข้ามข่าวที่มีหัวข้อเดิมอยู่แล้ว) · ลบข่าวตัวอย่างทั้งหมดด้วย sql/sample_news_delete.sql
SET NAMES utf8mb4;

INSERT INTO news (category_id, title, summary, content, cover, is_pinned, status, views, published_at)
  SELECT (SELECT id FROM categories WHERE name = 'ข่าวประชาสัมพันธ์' LIMIT 1), 'วิทยาลัยการอาชีพโพนทองจัดกิจกรรมจิตอาสาพัฒนาวัดและชุมชนรอบสถานศึกษา', 'ครู บุคลากร และนักเรียน นักศึกษาร่วมทำความสะอาดและปรับภูมิทัศน์วัดและพื้นที่สาธารณะในชุมชน',
    '<p>วิทยาลัยการอาชีพโพนทอง นำครู บุคลากร และนักเรียน นักศึกษา ร่วมกิจกรรมจิตอาสาพัฒนาวัดและพื้นที่สาธารณะรอบสถานศึกษา ทั้งการทำความสะอาด ตัดแต่งต้นไม้ และซ่อมแซมอุปกรณ์ไฟฟ้าที่ชำรุด</p><p>กิจกรรมนี้มุ่งปลูกฝังจิตสำนึกสาธารณะ ความรับผิดชอบต่อสังคม และสร้างความสัมพันธ์ที่ดีระหว่างวิทยาลัยกับชุมชน</p><p class="text-muted small mt-4">* ข่าวตัวอย่างสำหรับทดสอบระบบ</p>',
    'uploads/sample/sample-news-11.jpg', 0, 'published', 84, '2026-10-15 09:00:00' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM news WHERE title = 'วิทยาลัยการอาชีพโพนทองจัดกิจกรรมจิตอาสาพัฒนาวัดและชุมชนรอบสถานศึกษา');

INSERT INTO news (category_id, title, summary, content, cover, is_pinned, status, views, published_at)
  SELECT (SELECT id FROM categories WHERE name = 'ข่าวประชาสัมพันธ์' LIMIT 1), 'แผนกวิชาการโรงแรมจัดอบรมการผสมเครื่องดื่มและการบริการลูกค้าให้ผู้เรียน', 'ผู้เรียนฝึกปฏิบัติการบริการเครื่องดื่มและการต้อนรับลูกค้า เตรียมความพร้อมก่อนออกฝึกประสบการณ์วิชาชีพ',
    '<p>แผนกวิชาการโรงแรม จัดอบรมเชิงปฏิบัติการด้านการผสมเครื่องดื่มไม่มีแอลกอฮอล์ และมารยาทในการบริการลูกค้า ให้กับนักเรียน นักศึกษาก่อนออกฝึกประสบการณ์วิชาชีพในสถานประกอบการ</p><div class="row g-3"><div class="col-md-6"><h4>สิ่งที่ผู้เรียนได้ฝึก</h4><ul><li>การเตรียมอุปกรณ์และวัตถุดิบ</li><li>การจัดแต่งเครื่องดื่ม</li><li>การสื่อสารกับลูกค้า</li></ul></div><div class="col-md-6"><h4>ผลที่คาดหวัง</h4><p>ผู้เรียนมีความมั่นใจและพร้อมทำงานในธุรกิจโรงแรมและร้านอาหาร</p></div></div><p class="text-muted small mt-4">* ข่าวตัวอย่างสำหรับทดสอบระบบ</p>',
    'uploads/sample/sample-news-12.jpg', 0, 'published', 67, '2026-10-19 13:00:00' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM news WHERE title = 'แผนกวิชาการโรงแรมจัดอบรมการผสมเครื่องดื่มและการบริการลูกค้าให้ผู้เรียน');

INSERT INTO news (category_id, title, summary, content, cover, is_pinned, status, views, published_at)
  SELECT (SELECT id FROM categories WHERE name = 'ข่าวประกาศ' LIMIT 1), 'ประกาศรายชื่อผู้มีสิทธิ์ได้รับทุนการศึกษา ภาคเรียนที่ 2 ปีการศึกษา 2569', 'ให้นักเรียน นักศึกษาที่มีรายชื่อติดต่อรับทุนการศึกษาที่งานแนะแนวอาชีพและจัดหางาน',
    '<p>งานแนะแนวอาชีพและจัดหางาน แจ้งประกาศรายชื่อนักเรียน นักศึกษาผู้มีสิทธิ์ได้รับทุนการศึกษา ภาคเรียนที่ 2 ปีการศึกษา 2569 รายละเอียดตามเอกสารประกาศ</p><div class="alert alert-info"><strong>การติดต่อรับทุน</strong><p class="mb-0">นำบัตรประจำตัวนักเรียนมาแสดง และติดต่อในวันและเวลาราชการที่งานแนะแนวอาชีพและจัดหางาน</p></div><p class="text-muted small mt-4">* ข่าวตัวอย่างสำหรับทดสอบระบบ</p>',
    'uploads/sample/sample-news-13.jpg', 0, 'published', 156, '2026-10-17 08:30:00' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM news WHERE title = 'ประกาศรายชื่อผู้มีสิทธิ์ได้รับทุนการศึกษา ภาคเรียนที่ 2 ปีการศึกษา 2569');

INSERT INTO news (category_id, title, summary, content, cover, is_pinned, status, views, published_at)
  SELECT (SELECT id FROM categories WHERE name = 'ข่าวประกาศ' LIMIT 1), 'ประกาศแนวปฏิบัติการแต่งกายของนักเรียน นักศึกษา', 'ทบทวนระเบียบการแต่งกายและการไว้ทรงผมของผู้เรียน เพื่อความเป็นระเบียบเรียบร้อย',
    '<p>งานปกครอง ฝ่ายพัฒนากิจการนักเรียน นักศึกษา ขอแจ้งแนวปฏิบัติการแต่งกายและการไว้ทรงผมของนักเรียน นักศึกษา ให้เป็นไปตามระเบียบของสถานศึกษา</p><ul><li>แต่งเครื่องแบบให้ถูกต้องตามวันที่กำหนด</li><li>ชุดฝึกปฏิบัติงานใช้ในชั่วโมงเรียนภาคปฏิบัติ</li><li>ติดบัตรประจำตัวทุกครั้งเมื่ออยู่ในสถานศึกษา</li></ul><p>ผู้ปกครองสามารถสอบถามรายละเอียดเพิ่มเติมได้ที่ครูที่ปรึกษาหรืองานปกครอง</p><p class="text-muted small mt-4">* ข่าวตัวอย่างสำหรับทดสอบระบบ</p>',
    'uploads/sample/sample-news-14.jpg', 0, 'published', 99, '2026-10-27 15:30:00' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM news WHERE title = 'ประกาศแนวปฏิบัติการแต่งกายของนักเรียน นักศึกษา');

INSERT INTO news (category_id, title, summary, content, cover, is_pinned, status, views, published_at)
  SELECT (SELECT id FROM categories WHERE name = 'ข่าวรับสมัคร' LIMIT 1), 'รับสมัครนักเรียน นักศึกษาเข้าร่วมชมรมวิชาชีพ ภาคเรียนที่ 2/2569', 'เปิดรับสมัครสมาชิกชมรมวิชาชีพทุกแผนกวิชา ส่งเสริมทักษะเฉพาะทางและการทำงานเป็นทีม',
    '<p>องค์การนักวิชาชีพในอนาคตแห่งประเทศไทย (อวท.) วิทยาลัยการอาชีพโพนทอง เปิดรับสมัครนักเรียน นักศึกษาเข้าร่วมชมรมวิชาชีพ ภาคเรียนที่ 2 ปีการศึกษา 2569</p><p>ชมรมวิชาชีพเปิดโอกาสให้ผู้เรียนพัฒนาทักษะเฉพาะทาง ฝึกการทำงานเป็นทีม และเตรียมความพร้อมสู่การแข่งขันทักษะวิชาชีพ สมัครได้ที่ครูที่ปรึกษาชมรมของแต่ละแผนกวิชา</p><p class="text-muted small mt-4">* ข่าวตัวอย่างสำหรับทดสอบระบบ</p>',
    'uploads/sample/sample-news-15.jpg', 0, 'published', 118, '2026-10-18 10:00:00' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM news WHERE title = 'รับสมัครนักเรียน นักศึกษาเข้าร่วมชมรมวิชาชีพ ภาคเรียนที่ 2/2569');

INSERT INTO news (category_id, title, summary, content, cover, is_pinned, status, views, published_at)
  SELECT (SELECT id FROM categories WHERE name = 'ข่าวรับสมัคร' LIMIT 1), 'รับสมัครนักศึกษาระบบทวิภาคีร่วมกับสถานประกอบการ', 'เรียนในวิทยาลัยควบคู่การฝึกงานจริงในสถานประกอบการ พร้อมค่าตอบแทนระหว่างฝึก',
    '<p>วิทยาลัยการอาชีพโพนทอง ร่วมกับสถานประกอบการเครือข่าย เปิดรับสมัครนักศึกษาเข้าเรียนในระบบทวิภาคี ผู้เรียนจะได้เรียนทฤษฎีในวิทยาลัยและฝึกปฏิบัติงานจริงในสถานประกอบการ</p><h3>ประโยชน์ที่ได้รับ</h3><ul><li>ประสบการณ์การทำงานจริงตั้งแต่ระหว่างเรียน</li><li>ค่าตอบแทนระหว่างฝึกตามที่สถานประกอบการกำหนด</li><li>โอกาสได้รับการพิจารณาเข้าทำงานหลังสำเร็จการศึกษา</li></ul><p>สอบถามได้ที่งานทวิภาคี</p><p class="text-muted small mt-4">* ข่าวตัวอย่างสำหรับทดสอบระบบ</p>',
    'uploads/sample/sample-news-16.jpg', 0, 'published', 133, '2026-10-23 09:30:00' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM news WHERE title = 'รับสมัครนักศึกษาระบบทวิภาคีร่วมกับสถานประกอบการ');

INSERT INTO news (category_id, title, summary, content, cover, is_pinned, status, views, published_at)
  SELECT (SELECT id FROM categories WHERE name = 'ข่าวจัดซื้อจัดจ้าง' LIMIT 1), 'ประกาศประกวดราคาจ้างปรับปรุงห้องปฏิบัติการคอมพิวเตอร์', 'ประกวดราคาด้วยวิธีประกวดราคาอิเล็กทรอนิกส์ (e-bidding) รายละเอียดตามเอกสารประกาศ',
    '<p>วิทยาลัยการอาชีพโพนทอง มีความประสงค์จะประกวดราคาจ้างปรับปรุงห้องปฏิบัติการคอมพิวเตอร์ ด้วยวิธีประกวดราคาอิเล็กทรอนิกส์ (e-bidding)</p><p>ผู้สนใจสามารถดูรายละเอียดและดาวน์โหลดเอกสารประกวดราคาได้ที่ระบบการจัดซื้อจัดจ้างภาครัฐ (e-GP) และเอกสารแนบท้ายประกาศนี้</p><p class="text-muted small mt-4">* ข่าวตัวอย่างสำหรับทดสอบระบบ</p>',
    'uploads/sample/sample-news-17.jpg', 0, 'published', 37, '2026-10-16 14:00:00' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM news WHERE title = 'ประกาศประกวดราคาจ้างปรับปรุงห้องปฏิบัติการคอมพิวเตอร์');

INSERT INTO news (category_id, title, summary, content, cover, is_pinned, status, views, published_at)
  SELECT (SELECT id FROM categories WHERE name = 'ข่าวจัดซื้อจัดจ้าง' LIMIT 1), 'สรุปผลการจัดซื้อจัดจ้างประจำเดือนตุลาคม 2569', 'เผยแพร่สรุปผลการดำเนินการจัดซื้อจัดจ้างรายเดือน (แบบ สขร.1) เพื่อความโปร่งใส',
    '<p>วิทยาลัยการอาชีพโพนทอง ขอเผยแพร่สรุปผลการดำเนินการจัดซื้อจัดจ้าง ประจำเดือนตุลาคม 2569 ตามแบบ สขร.1 เพื่อให้เป็นไปตามหลักความโปร่งใสและตรวจสอบได้</p><p>รายละเอียดรายการ วงเงิน และผู้ได้รับการคัดเลือก ตามเอกสารแนบ</p><p class="text-muted small mt-4">* ข่าวตัวอย่างสำหรับทดสอบระบบ</p>',
    'uploads/sample/sample-news-18.jpg', 0, 'published', 29, '2026-10-30 10:30:00' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM news WHERE title = 'สรุปผลการจัดซื้อจัดจ้างประจำเดือนตุลาคม 2569');

INSERT INTO news (category_id, title, summary, content, cover, is_pinned, status, views, published_at)
  SELECT (SELECT id FROM categories WHERE name = 'ผลงานและรางวัล' LIMIT 1), 'ครูวิทยาลัยการอาชีพโพนทองได้รับรางวัลครูดีเด่นด้านการสอนวิชาชีพ', 'ยกย่องครูผู้มีผลงานโดดเด่นด้านการจัดการเรียนการสอนและพัฒนาผู้เรียน',
    '<p>ขอแสดงความยินดีกับครูวิทยาลัยการอาชีพโพนทอง ที่ได้รับการยกย่องเป็นครูดีเด่นด้านการสอนวิชาชีพ จากผลงานการพัฒนาสื่อการเรียนรู้และการจัดการเรียนการสอนที่เน้นการปฏิบัติจริง</p><p>รางวัลนี้สะท้อนความทุ่มเทของครูในการพัฒนาผู้เรียนให้มีทักษะตรงกับความต้องการของสถานประกอบการ</p><p class="text-muted small mt-4">* ข่าวตัวอย่างสำหรับทดสอบระบบ</p>',
    'uploads/sample/sample-news-19.jpg', 0, 'published', 176, '2026-10-20 11:30:00' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM news WHERE title = 'ครูวิทยาลัยการอาชีพโพนทองได้รับรางวัลครูดีเด่นด้านการสอนวิชาชีพ');

INSERT INTO news (category_id, title, summary, content, cover, is_pinned, status, views, published_at)
  SELECT (SELECT id FROM categories WHERE name = 'ผลงานและรางวัล' LIMIT 1), 'ทีมนักศึกษาได้รับรางวัลการแข่งขันทักษะวิชาชีพ ระดับภาค', 'นักศึกษาแผนกวิชาช่างเชื่อมโลหะและช่างไฟฟ้ากำลังคว้ารางวัลจากการแข่งขันทักษะวิชาชีพ',
    '<p>ขอแสดงความยินดีกับทีมนักศึกษาวิทยาลัยการอาชีพโพนทอง ที่ได้รับรางวัลจากการแข่งขันทักษะวิชาชีพ ในการประชุมวิชาการองค์การนักวิชาชีพในอนาคตแห่งประเทศไทย ระดับภาค</p><ul><li>ทักษะงานเชื่อมโลหะ</li><li>ทักษะการติดตั้งไฟฟ้าในอาคาร</li></ul><p>ขอขอบคุณครูผู้ฝึกสอนและผู้ปกครองที่ให้การสนับสนุนตลอดการเตรียมตัว</p><p class="text-muted small mt-4">* ข่าวตัวอย่างสำหรับทดสอบระบบ</p>',
    'uploads/sample/sample-news-20.jpg', 0, 'published', 201, '2026-10-29 16:30:00' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM news WHERE title = 'ทีมนักศึกษาได้รับรางวัลการแข่งขันทักษะวิชาชีพ ระดับภาค');

